/// One box-shadow layer: offsets, blur and spread in px, colour as 0xRRGGBBAA.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Shadow {
    pub x: f32,
    pub y: f32,
    pub blur: f32,
    pub spread: f32,
    pub inset: bool,
    pub color: u32,
}

